var safetynet = message.promulgation('safetynet');
if (safetynet !== null && safetynet.areaName !== null) {
    var safetynetService = CdiUtils.getBean(org.niord.core.promulgation.SafetyNetPromulgationService.class);
    var area = safetynetService.findAreaByName(
        safetynet.type.typeId,
        safetynet.areaName);
    if (area !== null) {
        params.put('area', area.toVo(org.niord.model.DataFilter.get().fields(org.niord.model.DataFilter.DETAILS)));
    }
}

